async function provisionGenericTenant(db, opts) {
  const country = opts.country || "\u0627\u0644\u064A\u0645\u0646";
  let tenantRow = (await db.select().from(tenants).where(eq4(tenants.code, opts.code)).limit(1))[0];
  if (!tenantRow) {
    const [created] = await db.insert(tenants).values({
      name: opts.name,
      code: opts.code,
      currency: opts.currency || "YER"
    }).returning();
    tenantRow = created;
  }
  const tid = tenantRow.id;
  const existingBranch = await db.select().from(branches).where(eq4(branches.tenantId, tid)).limit(1);
  if (existingBranch.length === 0) {
    await db.insert(branches).values({
      tenantId: tid,
      name: "\u0627\u0644\u0641\u0631\u0639 \u0627\u0644\u0631\u0626\u064A\u0633\u064A",
      code: "MAIN",
      city: "",
      isMain: true
    });
  }
  const existingSettings = await db.select().from(settings).where(eq4(settings.tenantId, tid)).limit(1);
  if (existingSettings.length === 0) {
    await db.insert(settings).values({
      tenantId: tid,
      institutionName: opts.name,
      country,
      currency: "\u0631\u064A\u0627\u0644 \u064A\u0645\u0646\u064A (YER)",
      accountingPeriod: String((/* @__PURE__ */ new Date()).getFullYear()),
      managerName: opts.name
    });
  }
  const acctCount = await db.$count(accounts, eq4(accounts.tenantId, tid));
  if (acctCount === 0) {
    const inserted = await db.insert(accounts).values(
      libraryAccounts.map((a) => ({
        tenantId: tid,
        code: a.code,
        name: a.name,
        type: a.type,
        isActive: true,
        isCustom: false,
        parentAccountId: null
      }))
    ).returning({ id: accounts.id, code: accounts.code });
    const codeToId = new Map(inserted.map((r) => [r.code, r.id]));
    for (const a of libraryAccounts) {
      if (a.parentCode && codeToId.has(a.parentCode)) {
        await db.update(accounts).set({ parentAccountId: codeToId.get(a.parentCode) }).where(and2(eq4(accounts.tenantId, tid), eq4(accounts.code, a.code)));
      }
    }
  }
  return tid;
}
