async function runRecurringExpenses(tenantId, userId = null) {
  const db = await getDb();
  if (!db) return { processed: 0, failed: 0, skipped: 0 };
  const now = /* @__PURE__ */ new Date();
  const due = await db.select().from(recurringExpenses).where(
    and3(
      eq5(recurringExpenses.tenantId, tenantId),
      eq5(recurringExpenses.status, "active"),
      eq5(recurringExpenses.approvalStatus, "approved"),
      lte(recurringExpenses.nextRunAt, now)
    )
  );
  let processed = 0;
  let failed = 0;
  let skipped = 0;
  for (const rec of due) {
    const existingRun = await db.select().from(recurringExpenseRuns).where(
      and3(
        eq5(recurringExpenseRuns.recurringExpenseId, rec.id),
        eq5(recurringExpenseRuns.scheduledDate, rec.nextRunAt)
      )
    ).limit(1);
    if (existingRun[0]) {
      skipped++;
      continue;
    }
    const [run] = await db.insert(recurringExpenseRuns).values({
      tenantId,
      recurringExpenseId: rec.id,
      runNumber: rec.occurrencesCount + 1,
      scheduledDate: rec.nextRunAt,
      status: "pending",
      amount: "0",
      totalAmount: "0"
    }).returning();
    await processRecurringExpenseRun(db, run, userId);
    const [finalRun] = await db.select().from(recurringExpenseRuns).where(eq5(recurringExpenseRuns.id, run.id)).limit(1);
    if (finalRun?.status === "completed") {
      processed++;
    } else {
      failed++;
    }
  }
  return { processed, failed, skipped };
}
async function generateUpcomingRuns(tenantId, months = 12) {
  const db = await getDb();
  if (!db) return [];
  const active = await db.select().from(recurringExpenses).where(
    and3(
      eq5(recurringExpenses.tenantId, tenantId),
      eq5(recurringExpenses.status, "active"),
      eq5(recurringExpenses.approvalStatus, "approved")
    )
  );
  const until = /* @__PURE__ */ new Date();
  until.setMonth(until.getMonth() + months);
  const upcoming = [];
  for (const rec of active) {
    let runDate = rec.nextRunAt ? new Date(rec.nextRunAt) : new Date(rec.startDate);
    let runNumber = rec.occurrencesCount + 1;
    while (runDate <= until && (!rec.maxOccurrences || runNumber <= rec.maxOccurrences) && (!rec.endDate || runDate <= new Date(rec.endDate))) {
      upcoming.push({
        recurringExpenseId: rec.id,
        recurringExpenseName: rec.name,
        runNumber,
        scheduledDate: new Date(runDate),
        amount: parseFloat(rec.amount),
        taxAmount: Math.round(
          parseFloat(rec.amount) * parseFloat(rec.taxRate || "0") / 100 * 100
        ) / 100,
        totalAmount: parseFloat(rec.amount) + Math.round(
          parseFloat(rec.amount) * parseFloat(rec.taxRate || "0") / 100 * 100
        ) / 100,
        frequency: rec.frequency
      });
      runDate = calculateNextRunDate(
        runDate,
        rec.frequency,
        rec.dayOfMonth,
        rec.dayOfWeek,
        rec.weekOfMonth
      );
      runNumber++;
    }
  }
  return upcoming.sort(
    (a, b) => a.scheduledDate.getTime() - b.scheduledDate.getTime()
  );
}

